-- Create "catalog_state" table
CREATE TABLE "catalog_state" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "version" bigint NOT NULL DEFAULT 1, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "catalog_state_single_row" CHECK (id = 1));
-- Create "cities" table
CREATE TABLE "cities" ("id" character varying NOT NULL, "revision" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "slug" character varying NOT NULL, "name" character varying NOT NULL, "header_images" jsonb NOT NULL, "map_svg_url" character varying NOT NULL DEFAULT '', "sort_order" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"), CONSTRAINT "cities_images_limit" CHECK (jsonb_array_length(header_images) <= 8), CONSTRAINT "cities_name_length" CHECK ((char_length((name)::text) >= 1) AND (char_length((name)::text) <= 32)), CONSTRAINT "cities_slug_format" CHECK ((slug)::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text), CONSTRAINT "cities_slug_length" CHECK (char_length((slug)::text) <= 32));
-- Create index "cities_slug_key" to table: "cities"
CREATE UNIQUE INDEX "cities_slug_key" ON "cities" ("slug");
-- Create index "city_sort_order_slug" to table: "cities"
CREATE INDEX "city_sort_order_slug" ON "cities" ("sort_order", "slug");
-- Create "rolling_stock_topics" table
CREATE TABLE "rolling_stock_topics" ("id" character varying NOT NULL, "revision" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "slug" character varying NOT NULL, "name" character varying NOT NULL, "rolling_stock_codes" jsonb NOT NULL, "cars" jsonb NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "rolling_stock_topics_name_length" CHECK ((char_length((name)::text) >= 1) AND (char_length((name)::text) <= 64)), CONSTRAINT "rolling_stock_topics_slug_format" CHECK ((slug)::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text));
-- Create index "rolling_stock_topics_slug_key" to table: "rolling_stock_topics"
CREATE UNIQUE INDEX "rolling_stock_topics_slug_key" ON "rolling_stock_topics" ("slug");
-- Create "rolling_stocks" table
CREATE TABLE "rolling_stocks" ("id" character varying NOT NULL, "revision" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "code" character varying NOT NULL, "length_m" numeric(6,2) NULL, "width_m" numeric(6,2) NULL, "capacity" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "rolling_stocks_code_length" CHECK ((char_length((code)::text) >= 1) AND (char_length((code)::text) <= 32)), CONSTRAINT "rolling_stocks_dimensions" CHECK (((length_m IS NULL) OR (length_m > (0)::numeric)) AND ((width_m IS NULL) OR (width_m > (0)::numeric)) AND ((capacity IS NULL) OR (capacity > 0))));
-- Create index "rolling_stocks_code_key" to table: "rolling_stocks"
CREATE UNIQUE INDEX "rolling_stocks_code_key" ON "rolling_stocks" ("code");
-- Create "lines" table
CREATE TABLE "lines" ("id" character varying NOT NULL, "revision" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "code" character varying NOT NULL, "name" character varying NOT NULL, "number" bigint NOT NULL DEFAULT 0, "status" character varying NOT NULL DEFAULT 'operating', "cars" bigint NOT NULL DEFAULT 0, "cars_addition" bigint NOT NULL DEFAULT 0, "stations" bigint NOT NULL DEFAULT 0, "length_km" numeric(8,2) NOT NULL DEFAULT 0, "color" character varying NOT NULL, "commenced_on" date NULL, "extended_on" date NULL, "is_loop" boolean NOT NULL DEFAULT false, "city_id" character varying NOT NULL, "rolling_stock_id" character varying NULL, PRIMARY KEY ("id"), CONSTRAINT "lines_cities_lines" FOREIGN KEY ("city_id") REFERENCES "cities" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "lines_rolling_stocks_lines" FOREIGN KEY ("rolling_stock_id") REFERENCES "rolling_stocks" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "lines_code_format" CHECK ((code)::text ~ '^[a-z0-9][a-z0-9-]{1,31}$'::text), CONSTRAINT "lines_color_format" CHECK ((color)::text ~ '^#[0-9A-Fa-f]{6}$'::text), CONSTRAINT "lines_counts" CHECK ((number >= 0) AND (cars >= 0) AND (cars_addition >= 0) AND (stations >= 0) AND (length_km >= (0)::numeric)), CONSTRAINT "lines_name_length" CHECK ((char_length((name)::text) >= 1) AND (char_length((name)::text) <= 32)));
-- Create index "line_city_id_number_code" to table: "lines"
CREATE INDEX "line_city_id_number_code" ON "lines" ("city_id", "number", "code");
-- Create index "line_status" to table: "lines"
CREATE INDEX "line_status" ON "lines" ("status");
-- Create index "lines_code_key" to table: "lines"
CREATE UNIQUE INDEX "lines_code_key" ON "lines" ("code");
